-- 5. Weeks 9-38: deloads in 13, 18, 27, 32 and the 37-38 taper.
with o as (select user_id as uid from public.profiles order by created_at limit 1)
insert into public.program_weeks (user_id, program_id, week_number, is_deload, notes)
select o.uid, p.id, v.week_number, v.is_deload, v.notes
from o join public.training_programs p on p.user_id = o.uid and p.name = 'ACL return'
cross join (values (9::smallint, false, 'On-ramp: find loads.'), (10, false, 'Block 1. Landing prep starts Friday (normal knee check only).'), (11, false, null), (12, false, 'Kazaglis visit 11/10: review the barbell, depth_past_90 and jog gates.'), (13, true, 'Deload + test. Kazaglis 11/10, PT progress note 11/19: review gates. Full test battery Sunday 11/22.'), (14, false, null), (15, false, null), (16, false, null), (17, false, null), (18, true, 'Holiday deload. Test Sunday 12/27.'), (19, false, null), (20, false, null), (21, false, null), (22, false, 'Sunday: first hop test battery (single, triple, crossover, 6 m timed) in the PT Tracker.'), (23, false, null), (24, false, null), (25, false, null), (26, false, 'Last week of Strength A.'), (27, true, 'Deload + monthly test Sunday.'), (28, false, null), (29, false, null), (30, false, null), (31, false, 'Last week of Power B.'), (32, true, 'Deload + monthly test Sunday.'), (33, false, null), (34, false, null), (35, false, null), (36, false, null), (37, true, 'Taper.'), (38, true, 'Taper. Full return-to-sport battery Sunday 5/16. rts gate eligible 5/17.')) as v(week_number, is_deload, notes)
on conflict (program_id, week_number) do update
  set is_deload = excluded.is_deload, notes = excluded.notes, deleted_at = null;

-- 6. Sessions: the same weekday slots in every block.
with o as (select user_id as uid from public.profiles order by created_at limit 1)
insert into public.program_sessions
  (user_id, block_id, day_of_week, sort_order, session_type, name, ride_kind,
   minutes_min, minutes_max, structure, gate_key, is_optional, notes)
select o.uid, b.id, v.d, v.s, v.t, v.n, v.rk, v.m1, v.m2, v.st, v.g, coalesce(v.op, false), v.nt
from o join public.training_programs p on p.user_id = o.uid and p.name = 'ACL return'
