      side_mode = excluded.side_mode, load_kind = excluded.load_kind,
      sets_min = excluded.sets_min, sets_max = excluded.sets_max,
      reps_min = excluded.reps_min, reps_max = excluded.reps_max, rir_target = excluded.rir_target,
      seconds_target = excluded.seconds_target, distance_meters_target = excluded.distance_meters_target,
      tempo = excluded.tempo, gate_key = excluded.gate_key, extra_gate_key = excluded.extra_gate_key,
      substitute_name = excluded.substitute_name, substitute_load_kind = excluded.substitute_load_kind,
      substitute_reps_min = excluded.substitute_reps_min, substitute_reps_max = excluded.substitute_reps_max,
      from_week = excluded.from_week, until_week = excluded.until_week,
      counts_as_quad_set = excluded.counts_as_quad_set, cue = excluded.cue, notes = excluded.notes,
      superset_group = excluded.superset_group, superset_order = excluded.superset_order,
      deleted_at = null;


-- 8. Settings (new keys only; edits made in Settings are kept), the steps
-- habit (8,000), and the three lift templates rebuilt from v2 Block 1.
with o as (select user_id as uid from public.profiles order by created_at limit 1)
insert into public.training_settings (user_id, key, value, text_value, label, unit, group_name, sort_order)
select o.uid, v.key, v.value, v.text_value, v.label, v.unit, v.group_name, v.sort_order
from o
cross join (values
  ('gait_drill', null::numeric, 'Slow march, then step-throughs to a metronome at preferred cadence +5%.', 'Lift-day gait drill (3 min)', null, 'Program', 15::smallint),
  ('plyo_work_seconds', 15::numeric, null, 'Work per plyo set', 's', 'Session time budget', 45::smallint)
) as v(key, value, text_value, label, unit, group_name, sort_order)
on conflict (user_id, key) do nothing;

with o as (select user_id as uid from public.profiles order by created_at limit 1)
update public.supplements s
set name = '8,000 steps'
from o
where s.user_id = o.uid and s.kind = 'habit' and s.name = '7,000 steps' and s.deleted_at is null;

with o as (select user_id as uid from public.profiles order by created_at limit 1)
update public.training_templates t
set name = v.name, definition = v.definition
from o
cross join (values
  (1::smallint, 'Mon Legs + Push', '{"notes": "program v2.1, 2026-10-19, Block 1 (weeks 10-12). The program card on /strength is the source of truth (knee check, gates, loads); use this list when that card is not showing. Warm-up 5 min: Peloton easy 3 min; band TKE 15/leg; bodyweight box squat x10; glute bridge x10. Gait drill 3 min: Slow march, then step-throughs to a metronome at preferred cadence +5%. Pairs: alternate A1 and A2, rest after the pair. Left leg first on per-leg work. No kneeling on the left knee; on and off benches leading with the right leg.", "exercises": [{"exerciseName": "Goblet Box Squat (to 90°)", "exerciseOrder": 1, "targetSets": 4, "targetReps": 12, "targetWeight": null, "targetRir": 2, "notes": "A1. Until the barbell gate; then Barbell Pin Squat (to 90°). Sit to the box at 90°; stand without rocking."}, {"exerciseName": "Lateral Raise", "exerciseOrder": 2, "targetSets": 3, "targetReps": 20, "targetWeight": null, "targetRir": 2, "notes": "A2. 15-20 reps. Lead with the elbows; stop at shoulder height."}, {"exerciseName": "Cuff Knee Extension (90→45°)", "exerciseOrder": 3, "targetSets": 3, "targetReps": 15, "targetWeight": null, "targetRir": 1, "notes": "12-15 reps. Per leg. Alternate L/R. Plate hung from the ankle cuff; stop at 45°. Left first. 3 s down, stop at 45° until full-range gate."}, {"exerciseName": "Barbell Hip Thrust", "exerciseOrder": 4, "targetSets": 3, "targetReps": 12, "targetWeight": null, "targetRir": 2, "notes": "C1. 10-12 reps. Ribs down, pause 1 s at the top."}, {"exerciseName": "Barbell Bench Press", "exerciseOrder": 5, "targetSets": 3, "targetReps": 10, "targetWeight": null, "targetRir": 2, "notes": "C2. 8-10 reps. Feet flat; do not tuck the left foot under the bench."}, {"exerciseName": "Incline Dumbbell Press", "exerciseOrder": 6, "targetSets": 3, "targetReps": 12, "targetWeight": null, "targetRir": 2, "notes": "D1. 10-12 reps. Shoulder blades back; control the bottom."}, {"exerciseName": "Single-Leg Calf Raise", "exerciseOrder": 7, "targetSets": 3, "targetReps": 15, "targetWeight": null, "targetRir": 1, "notes": "D2. 12-15 reps. Per leg. Off a plate, DB in hand. Left first. Full stretch off the plate, 1 s pause on top."}]}'::jsonb),
  (3::smallint, 'Wed Single-leg + Pull', '{"notes": "program v2.1, 2026-10-19, Block 1 (weeks 10-12). The program card on /strength is the source of truth (knee check, gates, loads); use this list when that card is not showing. Warm-up 5 min: Peloton easy 3 min; band TKE 15/leg; bodyweight box squat x10; glute bridge x10. Gait drill 3 min: Slow march, then step-throughs to a metronome at preferred cadence +5%. Pairs: alternate A1 and A2, rest after the pair. Left leg first on per-leg work. No kneeling on the left knee; on and off benches leading with the right leg.", "exercises": [{"exerciseName": "DB Step-Up (12\")", "exerciseOrder": 1, "targetSets": 3, "targetReps": 12, "targetWeight": null, "targetRir": 2, "notes": "A1. 10-12 reps. Per leg. Alternate legs. Left first. Push through the top foot only."}, {"exerciseName": "Pull-Up", "exerciseOrder": 2, "targetSets": 4, "targetReps": 4, "targetWeight": null, "targetRir": 1, "notes": "A2. 2-4 reps. 1 rep short of failure. Baseline about 4/3/3/2. Reach the bar from the bench; step down with the right leg. No jumping or dropping."}, {"exerciseName": "Split Squat (to 90°)", "exerciseOrder": 3, "targetSets": 3, "targetReps": 12, "targetWeight": null, "targetRir": 2, "notes": "B1. 10-12 reps. Per leg. From week 11: rear foot elevated. Left first. Front knee to 90°, tracking over the toes."}, {"exerciseName": "Dumbbell Row", "exerciseOrder": 4, "targetSets": 4, "targetReps": 12, "targetWeight": null, "targetRir": 2, "notes": "B2. 10-12 reps. 1-arm, bench-supported. Bench-supported; pull to the hip."}, {"exerciseName": "Slider Hamstring Curl", "exerciseOrder": 5, "targetSets": 3, "targetReps": 12, "targetWeight": null, "targetRir": 1, "notes": "C1. 10-12 reps. Hips up the whole set; slide out slowly."}, {"exerciseName": "Face Pull", "exerciseOrder": 6, "targetSets": 3, "targetReps": 20, "targetWeight": null, "targetRir": 2, "notes": "C2. 15-20 reps. Pull to the eyes, thumbs back."}, {"exerciseName": "Dumbbell Curl", "exerciseOrder": 7, "targetSets": 2, "targetReps": 15, "targetWeight": null, "targetRir": 2, "notes": "C3. 12-15 reps. No swing, full range."}]}'::jsonb),
  (5::smallint, 'Fri Quad + Arms', '{"notes": "program v2.1, 2026-10-19, Block 1 (weeks 10-12). The program card on /strength is the source of truth (knee check, gates, loads); use this list when that card is not showing. Warm-up 5 min: Peloton easy 3 min; band TKE 15/leg; bodyweight box squat x10; glute bridge x10. Gait drill 3 min: Slow march, then step-throughs to a metronome at preferred cadence +5%. Pairs: alternate A1 and A2, rest after the pair. Left leg first on per-leg work. No kneeling on the left knee; on and off benches leading with the right leg.", "exercises": [{"exerciseName": "Squat to Calf Raise", "exerciseOrder": 1, "targetSets": 2, "targetReps": 10, "targetWeight": null, "targetRir": null, "notes": "Normal knee check only. Landing prep, normal knee check only. Land quiet, knees over toes, hold 2 s. Smooth squat, drive up onto the toes."}, {"exerciseName": "Snap-Down to Stick", "exerciseOrder": 2, "targetSets": 3, "targetReps": 5, "targetWeight": null, "targetRir": null, "notes": "Normal knee check only. Landing prep, normal knee check only. Land quiet, knees over toes, hold 2 s. Land quiet, knees over toes, hold 2 s."}, {"exerciseName": "Double-Leg Pogo (low)", "exerciseOrder": 3, "targetSets": 2, "targetReps": 10, "targetWeight": null, "targetRir": null, "notes": "Normal knee check only. Landing prep, normal knee check only. Land quiet, knees over toes, hold 2 s. Stiff ankles, small quiet bounces."}, {"exerciseName": "Spanish Squat", "exerciseOrder": 4, "targetSets": 3, "targetReps": null, "targetWeight": null, "targetRir": null, "notes": "A1. 45 s. Heavy band, no deeper than 60°. Band behind the knees, shins vertical, no deeper than 60°."}, {"exerciseName": "Chin-Up", "exerciseOrder": 5, "targetSets": 3, "targetReps": 5, "targetWeight": null, "targetRir": 1, "notes": "A2. 3-5 reps. 1 rep short of failure. Reach the bar from the bench; step down with the right leg. No jumping or dropping."}, {"exerciseName": "Isometric Knee Extension (90°)", "exerciseOrder": 6, "targetSets": 5, "targetReps": null, "targetWeight": null, "targetRir": null, "notes": "5 s max, log peak N, per leg. Strapped, crane scale; log peak N. Alternate L/R. Left first. 5-s ramp, don''t jerk; strap level and perpendicular to the shin."}, {"exerciseName": "Heel-Elevated Goblet Squat (to 90°)", "exerciseOrder": 7, "targetSets": 3, "targetReps": 12, "targetWeight": null, "targetRir": 2, "notes": "C1. Heels up, torso tall, knees forward over the toes."}, {"exerciseName": "Close-Grip Bench Press", "exerciseOrder": 8, "targetSets": 3, "targetReps": 10, "targetWeight": null, "targetRir": 2, "notes": "C2. 8-10 reps. Feet flat; elbows tucked."}, {"exerciseName": "DB Single-Leg RDL", "exerciseOrder": 9, "targetSets": 3, "targetReps": 10, "targetWeight": null, "targetRir": 2, "notes": "D1. Per leg. Left first. Hinge at the hip, hips square, soft knee."}, {"exerciseName": "Dumbbell Shoulder Press", "exerciseOrder": 10, "targetSets": 3, "targetReps": 12, "targetWeight": null, "targetRir": 2, "notes": "D2. 10-12 reps. Seated. Ribs down, press straight up."}, {"exerciseName": "Tricep Extension", "exerciseOrder": 11, "targetSets": 2, "targetReps": 15, "targetWeight": null, "targetRir": 2, "notes": "D3. 12-15 reps. Overhead DB. Elbows in, full stretch."}]}'::jsonb)
) as v(day, name, definition)
where t.user_id = o.uid and t.template_type = 'strength' and t.deleted_at is null
  and t.scheduled_day_of_week = v.day;

-- 9. Checks: a mismatch fails the cast below (the error text names it), and
-- the whole seed rolls back. Plain SQL (no DO block, no DROP), so the
-- Supabase connector runs it without asking for confirmation.
with p as (
  select p.id from public.training_programs p
  join public.profiles pr on pr.user_id = p.user_id
  where p.name = 'ACL return' order by pr.created_at limit 1
), c as (
  select
    (select count(*) from public.program_blocks b, p where b.program_id = p.id and b.deleted_at is null) as blocks,
    (select count(*) from public.program_sessions s join public.program_blocks b on b.id = s.block_id, p
      where b.program_id = p.id and s.deleted_at is null and b.deleted_at is null) as sessions,
    (select count(*) from public.program_exercises e join public.program_sessions s on s.id = e.program_session_id
      join public.program_blocks b on b.id = s.block_id, p
      where b.program_id = p.id and e.deleted_at is null and s.deleted_at is null and b.deleted_at is null) as exercises,
    (select count(*) from public.program_weeks w, p where w.program_id = p.id and w.deleted_at is null
      and w.is_deload and w.week_number in (13, 18, 27, 32)) as deloads
)
select ('v2 seed check failed: blocks ' || blocks || '/14, sessions ' || sessions
  || '/93, exercises ' || exercises || '/327, deloads ' || deloads || '/4')::int
from c
where blocks <> 14 or sessions <> 93 or exercises <> 327 or deloads <> 4;
